import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"46、【升】 巽下坤上","description":"周易集注 - 46、【升】 巽下坤上","frontmatter":{"title":"46、【升】 巽下坤上","description":"周易集注 - 46、【升】 巽下坤上"},"headers":[],"relativePath":"zh/classics/jizhu/050.md","filePath":"zh/classics/jizhu/050.md"}'),h={name:"zh/classics/jizhu/050.md"};function t(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_46、【升】-巽下坤上" tabindex="-1">46、【升】 巽下坤上 <a class="header-anchor" href="#_46、【升】-巽下坤上" aria-label="Permalink to “46、【升】 巽下坤上”">​</a></h1><p>升者，进而上也。为卦巽下坤上，木生地中，长而益高，升之象也。又综萃，萃下卦之坤，上升而为升之上卦，亦升之象也。《序卦》：萃者聚也，聚而上者谓之升，故受之以升，所以次萃。</p><p>言占得此卦者大亨，用见大人，不可忧惧，从南方行则吉，所以元亨也。不曰利见而曰用见者，九二虽大人，乃臣位，六五之君欲用九二，则见之也。六四王用亨于岐山，即此用字也。勿恤者，本卦大象坎，有忧恤之象，故教之以勿恤。南征吉者，文王圆图，巽东南之卦，过离而至坤，是巽升于坤，故南征吉。若东行，则至震，非升矣。</p><p>《彖》曰：柔以时升，巽而顺，刚中而应，是以大亨。用见大人，勿恤，有庆也。南征吉，志行也。</p><p>以卦综释卦名，以卦德卦体释卦辞。柔者坤土也，本卦综萃，二卦同体，文王综为一卦，故《杂卦》曰“萃聚而升不来”也。柔以时升者，萃下卦之坤，升而为升之上卦也。柔本不能升，故以时升，所以名升。内巽外顺，则心不躁妄，行不悖理。又我有刚中之德，而六五以顺应之，岂不能升，所以元亨。有庆者，庆幸其道之得行，勿恤者此也。志行者，心期其道之必行，吉者此也。有庆志行者，即元亨也。</p><h3 id="《象》曰-地中生木-升-君子以顺德-积小以高大。" tabindex="-1">《象》曰：地中生木，升，君子以顺德，积小以高大。 <a class="header-anchor" href="#《象》曰-地中生木-升-君子以顺德-积小以高大。" aria-label="Permalink to “《象》曰：地中生木，升，君子以顺德，积小以高大。”">​</a></h3><p>本卦以坤土生木而得名，故曰君子以顺德，坤顺之德，即敬以直内，义以方外也。积者，日积月累，如地中生木，不觉其高大也。巽为高，高之象也。</p><p>初六，允升大吉。</p><p>允者信也，本卦原是坤土上升，初与四皆坤土，故允升。</p><p>初六柔顺居初，当升之时，与四相信而合志，占者如是，必能升矣，故大吉。</p><h3 id="《象》曰-允升大吉-上合志也。" tabindex="-1">《象》曰：允升大吉，上合志也。 <a class="header-anchor" href="#《象》曰-允升大吉-上合志也。" aria-label="Permalink to “《象》曰：允升大吉，上合志也。”">​</a></h3><p>与四合志，故允升。大畜九三与上九皆阳爻，然本卦皆欲畜极而通，故《小象》曰“上合志也”。此卦初居内卦之初，四居外卦之下，因柔以时升，皆欲升者也，故《小象》亦曰“上合志也”。</p><p>九二，孚乃利用禴，无咎。</p><p>九二以阳刚居中，六五以柔顺应之，盖孚信之至者矣，故有利用薄祭，亦可交神之象。占者如是，得遂其升，而有喜矣，故无咎。升综萃，萃六二引者阴柔也，此刚中，故止言孚乃利用禴。</p><h3 id="《象》曰-九二之孚-有喜也。" tabindex="-1">《象》曰：九二之孚，有喜也。 <a class="header-anchor" href="#《象》曰-九二之孚-有喜也。" aria-label="Permalink to “《象》曰：九二之孚，有喜也。”">​</a></h3><p>有喜者，喜得其升也。盖诚信之至，则君必信任之专，得以升矣。周公许之曰无咎，孔子曰君臣相孚，岂止无咎，且有喜也。中爻兑，喜悦之象也。</p><p>九三，升虚邑。</p><p>阳实阴虚，上体坤，有国邑之象，详见谦卦。以三升四，以实升虚，故曰升虚邑。或曰：四邑为邱，四邱为虚，非空虚也，乃邱虚也，亦通。</p><p>九三以阳刚之才，当升之时，而进临于坤，故有升虚邑之象。占者得此，其升而无疑者可知矣。</p><h3 id="《象》曰-升虚邑-无所疑也。" tabindex="-1">《象》曰：升虚邑，无所疑也。 <a class="header-anchor" href="#《象》曰-升虚邑-无所疑也。" aria-label="Permalink to “《象》曰：升虚邑，无所疑也。”">​</a></h3><p>本卦六五之君阴柔，九二之臣阳刚，似君弱臣强，正人之所疑也。况当升之时，自臣位渐升于君位，使四乃阳刚，则逼其五矣，安得而不疑?今升虚邑，阴土与五同体，故无所疑。</p><p>六四，王用亨于岐山，吉无咎。</p><p>坤错干，干为君，王之象也。王，指六五也。物两为岐，故曰岐路，两路也。坤上两拆，岐之象也。随卦兑为西，故曰西山，此两拆，故曰岐山。中爻震综艮，山之象也。则三四五皆山矣，皆因有此象，故以岐西二字别之。前儒不知象，乃曰岐山在西，失象之旨矣。此言岐山指四也，亨者通也，与公用亨于天子，王用亨于西山亨字同。王用亨于岐山者，即用见大人也。言六五欲用乎九二，乃通于四而求之也。四爻皆言升，独二与五为正应，故曰用禴。四与五相比，故曰用亨，盖君位不可升也。二用禴而五用亨，上下相用，正所谓刚中而应也，何吉如之，故吉而无咎。</p><p>六四以柔居柔，与五同体，盖顺事乎五之至者也，故六五欲用乎九二，乃通乎四以求之，故有王用亨于岐山之象，吉而无咎之道也，故其象占如此。</p><h3 id="《象》曰-王用亨于岐山-顺事也。" tabindex="-1">《象》曰：王用亨于岐山，顺事也。 <a class="header-anchor" href="#《象》曰-王用亨于岐山-顺事也。" aria-label="Permalink to “《象》曰：王用亨于岐山，顺事也。”">​</a></h3><p>四本顺体，又以柔居柔，得正顺事乎五，故五欲用乎九二，乃通乎四以求之也。四若非正，则成容悦之小人，安能通乎其二。</p><p>六五，贞吉，升阶。</p><p>王用亨于岐山，上孚乎下，贤君之事也。九二即觐君而升阶，下孚于上，良臣之事也，故先言贞吉之占，而后言升阶之象。阶者阶梯也，如梯之等差也。</p><p>六五以柔居尊，下任刚中之贤，乃通于四以求之，贞而且吉者也。九二当升之时，因六五用六四之求，即觐君而升阶矣。上下相孚，故其占象如此。</p><h3 id="《象》曰-贞吉升阶-大得志也。" tabindex="-1">《象》曰：贞吉升阶，大得志也。 <a class="header-anchor" href="#《象》曰-贞吉升阶-大得志也。" aria-label="Permalink to “《象》曰：贞吉升阶，大得志也。”">​</a></h3><p>大得志，即彖辞有庆志行也。</p><p>上六，冥升，利于不息之贞。</p><p>冥与冥豫之冥同，昏于升而不知止者也。坤为迷冥之象也。不息之贞，天理也，惟天理可以常升而不已，若富贵利达，涉于人欲之私，而非天理者，则有消长矣。冥豫动体，故教之以豫。冥升顺体，故教之以贞。</p><p>上六居升之极，乃昏于升而不知止者也，有冥升之象，故圣人教占者曰，升而不已，惟利不息之贞，他非所利也，为占者开迁善之门如此。</p><h3 id="《象》曰-冥升在上-消不富也。" tabindex="-1">《象》曰：冥升在上，消不富也。 <a class="header-anchor" href="#《象》曰-冥升在上-消不富也。" aria-label="Permalink to “《象》曰：冥升在上，消不富也。”">​</a></h3><p>消者消其所升之业也，富者富有也。凡升者，乃天理不息之贞，则成富有之业矣。若升其人欲之私，往而不返，溺而不止，则盈者必虚，泰者必否，见其日消而不见其长，消而不富矣，故曰消不富也。本卦下体巽，巽为富，此爻外卦，故曰不富。亦如无妄二爻，未入巽之位，曰未富。</p>',36)])])}const f=e(h,[["render",t]]);export{_ as __pageData,f as default};
